      "Веретено с недопряденной нитью ещё тёплое, словно его только что отложили.",
      "«Эхо» называет кружку, принесённую сверху: ручка отбита, а надпись «Ковчег» на боку кто-то процарапал шилом, чтобы читалась пальцами.",
      "Пальцы натыкаются на волчок из твёрдого ореха: если его запустить, он поёт тонким голосом.",
