      "Под рукой — фляга, оплетённая травяным шнуром, и в ней плещется что-то густое.",
      "«Эхо» узнаёт ковш, выдолбленный из сухого гриба-трутовика: он лёгкий, как пустая коробка.",
      "Пальцы находят сундучок с выпуклой надписью на крышке: «Не открывать до праздника». Праздник, похоже, ещё не наступил.",
      "На полу лежит тряпичный мяч, набитый шерстью, а внутри зашит бубенчик, чтобы мяч можно было найти.",
