      "«Эхо» называет глиняную лампу без фитиля, пустую и холодную: её принесли по привычке, но зажигать здесь незачем.",
      "В углу стоит каска со стройки ОКО, превращённая в цветочный горшок: в ней растёт трава, которая звенит.",
