      "«Эхо» называет подзорную трубу, принесённую сверху: смотреть в неё здесь не на что, и в окуляр кто-то вставил свёрнутую записку.",
      "Брусок мыла из золы завёрнут в лист, и на нём выдавлен отпечаток ладони.",
