      "Машинный голос надиктовывает письмо, в котором нет ничего, кроме вежливости: «Настоящим сообщаем. С совершенным почтением».",
      "Тонко дребезжит стекло в рамке на стене и затихает, только когда смолкает пресс.",
      "В углах шуршит щётка уборщика: он метёт с одинаковой силой и там, где пыли нет совсем.",
