      "Кто-то разогнул скрепку в прямую проволоку, а потом снова согнул — уже в маленького человечка, упёршего руки в боки.",
      "Коробка с кнопками рассортирована по длине иглы, и одна пустая ячейка подписана: «Утеряно. Ищем».",
      "«Эхо» называет перфокарту, и под пальцами её аккуратные дырочки складываются в подобие звёздного неба.",
