      "У деревянных счётов не хватает одной костяшки, и на её место надета гайка подходящего размера.",
      "Высохшая штемпельная подушка твёрдая, как камень; кто-то пробовал размочить её маслом, и теперь она скользкая.",
      "Моток бечёвки для подшивки дел смотан идеально ровно, виток к витку, как на заводской катушке.",
