      "Жестянка из-под леденцов, принесённая из «Ковчега», теперь хранит аккуратно уложенные предохранители.",
      "Стальная линейка размечена словами, а не цифрами: «один», «два», «три» — и так до самого конца.",
      "Компостер на цепочке лязгает от любого движения с такой обидой, что хочется извиниться.",
      "Лупа в латунной оправе треснула, и трещину заклеили полоской бумаги со штампом «Исправно».",
      "Маленькое зеркальце на длинной ручке нужно, чтобы заглядывать внутрь механизмов; глядеть в него здесь некому, но оно учтено.",
      "Чернильница-непроливайка до краёв налита машинным маслом вместо чернил.",
      "В картонной коробке лежат визитные карточки, и на всех одно и то же: «ОКО. Слушаю».",
      "Пачка бланков «Заявление о выдаче бланка заявления» перевязана шпагатом крест-накрест.",
      "Резиновый напальчник для счёта бумаг надет на тонкий стальной стержень, изображающий палец.",
      "Конверт запечатан сургучом с трёх сторон и открыт с четвёртой — видимо, так удобнее проверять.",
