      "Записная книжка на застёжке пуста, кроме одной страницы, где аккуратно выведено: «Здравствуйте».",
      "Банка полна нарезанных полосок бумаги — заготовок для бирок, а сверху лежит готовая бирка с надписью «Бирка».",
