      "Пустая рамка для фотографии снабжена бирочкой: «Фотография не поступала».",
      "Электрический звонок висит без кнопки, а провода его аккуратно заизолированы и подписаны: «Звонить некому».",
      "Стальные перья для ручек разложены в коробке по нажиму, от самого мягкого до самого злого.",
      "Кожаная перчатка лежит одна, с номером на манжете; вторая, видимо, числится где-то ещё.",
