      "Над дверью строгая табличка, перевёрнутая. «Эхо» разворачивает её: «Вход в верхней одежде запрещён». Холод здесь, видимо, считается одеждой.",
      "Таблица умножения висит задом наперёд, и «Эхо», перевернув, читает строчку вслух: «Четыре — это дважды два».",
      "На стене плакат о слухе. «Эхо» переворачивает его: «Береги уши — надевай наушники». Кто-то пририсовал к наушникам третье ухо.",
      "Карточка на двери: «Спасибо, что не шумите». Перевернув, «Эхо» читает её шёпотом, и стены всё равно вежливо отвечают: «шумите».",
      "Трафаретная надпись над входом читается в обратную сторону: «Последний закрывает дверь». Ниже маркером: «Последний здесь — каждый».",
      "Наклейка с яблоком на стене «Эхо» переворачивает: «Чистота — залог здоровья». Под ней кто-то дописал: «Зеркальная — тоже».",
      "Листок у косяка «Эхо» разворачивает и читает: «Пропуск предъявлять в развёрнутом виде». И уточняет: здесь — в свёрнутом.",
      "На стене выцарапано: «Проверь дозиметр». Буквы вывернуты, и «Эхо», перевернув их, всерьёз просит так и сделать.",
      "Перевёрнутая табличка у входа: «Ответственный за пожарную безопасность», а имя после двоеточия стёрто так, что «Эхо» читает только тишину.",
      "Висит календарь с котятами; «Эхо» переворачивает подпись под котёнком и читает: «Не будите меня». Котята, говорит оно, спят на всех листах.",
      "Плакат у двери гласит, если его перевернуть: «Будьте внимательны: вас слышат». Внизу дописано: «И повторяют».",
      "Записка на скотче «Эхо» переворачивает: «Не уходите далеко, я сейчас». Под ней ещё раз то же самое, тем же почерком, но отражённое обратно.",
