      "Катушка магнитофонной ленты с наклейкой: «Слушать одному».",
      "Рулончик ленты самописца перевязан ниткой, и «Эхо» говорит, что линия на нём красная и вся в острых пиках.",
      "Перо от самописца, тонкое, как игла, бережно завёрнуто в бумажку.",
      "Наушники на проволочном оголовье, одна чашка треснула и прихвачена изолентой.",
      "Микрофон в сетчатом колпаке висит на длинном проводе, и провод уходит прямо в стену.",
      "Оплывшая свеча на блюдце, а рядом коробок, в котором осталась одна спичка.",
      "Карбидная лампа с помятым бачком: капельник забит, и внутри что-то сухо шуршит.",
      "Фляга в суконном чехле пуста, и крышка болтается на цепочке.",
      "Моток пеньковой верёвки сложен аккуратной восьмёркой, как складывают для спуска.",
      "Латунный сигнальный свисток на шнурке весь покрыт шершавым налётом.",
      "Медный колокольчик без язычка: качнёшь его — и он молчит.",
      "Кувалда с рукоятью, перемотанной изолентой в три слоя.",
      "Шарошка от бурового долота — зубчатая, тяжёлая, с кулак, и зубья стёрты, как старые зубы.",
      "Столбик керна, завёрнутый в газету, тёплый на ощупь, как хлеб.",
      "Камень с дыркой посередине продет на суровую нитку: кто-то носил его на шее.",
      "«Справочник бурового мастера» с загнутыми уголками, а на полях — пометки карандашом.",
      "Тетрадь в клеёнчатой обложке исписана столбиками чисел, и последний столбик не подбит.",
      "Конверт без марки и без адреса, заклеенный и тяжёлый на ощупь.",
      "Открытка с ландышами, и на обороте ни единой строчки.",
      "Фотокарточка с обломанным уголком; «Эхо» читает только надпись на обороте: «На память о смене».",
      "Шахматный конь с отбитой гривой, гладкий от пальцев.",
      "Костяшка домино «пусто-пусто», холодная и тяжёлая.",
      "Колода карт перетянута аптечной резинкой, и одной карты в ней не хватает.",
      "Сдутый резиновый мяч с полосой посередине, мягкий, как переспелое яблоко.",
      "Детская галоша, одна, с налипшей глиной.",
      "Вязаный подшлемник растянут и пропах потом и мазутом.",
      "Респиратор с ватным фильтром, и вата внутри задубела от пыли.",
      "Защитные очки на резинке, стёкла в мелких царапинах, шершавые на ощупь.",
      "Шапка-ушанка с ушами, завязанными на макушке, и мех на ней свалялся.",
      "Валенок в резиновой галоше, тяжёлый и сырой изнутри.",
      "Жестяная коробка из-под леденцов, и в ней гремят винтики, гайки и одна серёжка.",
      "Спичечный коробок, а в нём вместо спичек — молочный зуб и бумажка: «Мышке».",
      "Круглая печать на деревянной ручке; «Эхо» читает зеркальные буквы: «Профком».",
      "Чугунный дырокол, тяжёлый, как утюг, с застрявшим в нём кружочком бумаги.",
      "Пресс-папье с промокашкой, и на промокашке отпечатались чьи-то строчки задом наперёд.",
      "Цепочка из скрепок длиной в руку — кто-то коротал так дежурство.",
      "Гвоздь, согнутый в аккуратное колечко, будто кто-то сделал себе перстень.",
      "Самодельный нож из ножовочного полотна, рукоять обмотана шнурком.",
      "Коробочка зубного порошка, высохшего в мел.",
      "Бутылка из-под кефира с засохшим букетиком в широком горле.",
      "Гвоздь-наколка на дощечке, и на него надета стопка бумажных нарядов, проткнутых посередине.",
      "Ключ на кольце с картонной биркой, на которой написано: «От всего».",
      "Струна, свёрнутая кольцом, — от гитары или от балалайки, «Эхо» не уверено.",
      "Деревянная свистулька в виде птички, новенькая: в неё, похоже, так ни разу и не дунули.",
      "Железная кружка с надписью «Лучшему помбуру», погнутая, будто ею забивали гвоздь.",
      "Пустой пузырёк из-под чернил, а в нём свёрнутая трубочкой записка, которую не вытащить.",
      "Кусок бархата с бахромой — край скатерти, отрезанный ножницами, — сложен, как платок.",
      "Самодельный светильник из консервной банки с фитилём из шнурка.",
      "Обломок рейки с частыми зарубками — самодельная линейка, которой мерили что-то очень маленькое.",
      "Лист кальки свёрнут в трубку, и на нём карандашом начерчен разрез скважины, у которого нет низа.",
      "Медная дверная ручка, отвинченная и положенная отдельно, будто её собирались унести с собой.",
      "Ситечко для чая в форме яйца на цепочке, забитое старой заваркой."
